1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	
5	const messages = defineMessages({
6	  positionLabel: {
7	    id: 'slide_indicator.position.label',
8	    defaultMessage: 'Image {current} of {total}',
9	  },
10	});
11	
12	const ZIMM_SLIDE_INDICATOR_RECIPE = 'ZimmSlideIndicator';
13	
14	type ZimmSlideIndicatorProps = {
15	  /** Total number of images/slides the strip represents. */
16	  count: number;
17	  /** Index (0-based) of the currently active/visible slide. Out-of-range values are clamped. */
18	  activeIndex: number;
19	};
20	
21	/**
22	 * Molecule — read-only image-position indicator for touch devices (tablet + mobile) on the
23	 * PDP/card image strip. Figma node 40002536:7957 ("Slide indicator"): a segmented 1px hairline
24	 * strip, one segment per image, the active segment picked out by colour. NOT floating dots.
25	 *
26	 * Touch-only per the resolved arrows-vs-indicator split (SFCC-236): hover-capable pointers get
27	 * prev/next arrow buttons instead (a separate component) and never render this molecule.
28	 * Because no arrows exist wherever this DOES render, it is the *sole* position signal
29	 * available there — the root is exposed (`role="group"` + a computed `aria-label`), never
30	 * `aria-hidden`, while the individual segments are purely decorative (`aria-hidden`) so
31	 * assistive tech announces the position once via the group label, not once per segment.
32	 *
33	 * Renders nothing for `count <= 1` — a single image has no position to indicate among.
34	 */
35	export const ZimmSlideIndicator = ({ count, activeIndex }: ZimmSlideIndicatorProps) => {
36	  const intl = useIntl();
37	
38	  // Out-of-range clamps rather than throwing: activeIndex < 0 treats as the first slide,
39	  // activeIndex >= count treats as the last. Written explicitly rather than relying on
40	  // Array.map/index lookups to silently no-op on an out-of-range value.
41	  const clampedIndex = Math.min(Math.max(activeIndex, 0), count - 1);
42	
43	  // Two static resolutions (isActive: false / true), not one per rendered segment — calling
44	  // useMultiStyleConfig inside the render loop below would be a conditional/looped hook call.
45	  // Which of the two resolved objects applies to a given segment is picked per-element in the
46	  // map below instead.
47	  const styles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: false });
48	  const activeStyles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: true });
49	
50	  // A single image has nothing to indicate a position among.
51	  if (count <= 1) return null;
52	
53	  const label = intl.formatMessage(messages.positionLabel, {
54	    current: clampedIndex + 1,
55	    total: count,
56	  });
57	
58	  return (
59	    <chakra.div role="group" aria-label={label} __css={styles.root}>
60	      {Array.from({ length: count }, (_, i) => {
61	        const isActive = i === clampedIndex;
62	        return (
63	          <chakra.div
64	            key={i}
65	            aria-hidden
66	            data-active={isActive ? 'true' : undefined}
67	            __css={isActive ? activeStyles.dot : styles.dot}
68	          />
69	        );
70	      })}
71	    </chakra.div>
72	  );
73	};
74	
75	export default ZimmSlideIndicator;
