1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
2	import { ZimmSlideIndicator } from './index';
3	
4	const meta: Meta<typeof ZimmSlideIndicator> = {
5	  title: 'Commerce/ZimmSlideIndicator',
6	  component: ZimmSlideIndicator,
7	  parameters: { layout: 'padded' },
8	};
9	
10	export default meta;
11	type Story = StoryObj<typeof ZimmSlideIndicator>;
12	
13	/** Figma 40002536:7957 — touch-only position indicator, 5 images, first slide active. */
14	export const Default: Story = {
15	  args: {
16	    count: 5,
17	    activeIndex: 0,
18	  },
19	};
20	
21	/** `Qty images = 5` Figma variant set, a middle slide active. */
22	export const FiveImages: Story = {
23	  args: {
24	    count: 5,
25	    activeIndex: 2,
26	  },
27	};
28	
29	/** `Qty images = 8` Figma variant set, a middle slide active. */
30	export const EightImages: Story = {
31	  args: {
32	    count: 8,
33	    activeIndex: 3,
34	  },
35	};
36	
37	/** First slide selected. */
38	export const FirstSelected: Story = {
39	  args: {
40	    count: 5,
41	    activeIndex: 0,
42	  },
43	};
44	
45	/** Last slide selected. */
46	export const LastSelected: Story = {
47	  args: {
48	    count: 5,
49	    activeIndex: 4,
50	  },
51	};
